@bp.post("")
@require_roles("PlatformAdmin")
def register_rider():
    body = get_json_body()
    name = require_str(body, "name", max_len=120)
    phone = require_str(body, "phone", max_len=40)
    with lock():
        for r in store.riders.values():
            if r["phone"] == phone:
                raise ApiError("ERR_VALIDATION", "Phone must be unique across riders.")
        t = now()
        rid = gen_id()
        rec = {
