        a["status"] = "DELIVERED"
        a["delivered_at"] = iso_z(t)

        # 2. Set actual_delivery_time, minutes_late.
        promised_dt = _parse_iso(order["promised_delivery_time"])
        actual_dt = t
        order["actual_delivery_time"] = iso_z(actual_dt)
        delta = (actual_dt - promised_dt).total_seconds()
        if delta <= 0:
