@bp.post("/<oid>/ready")
@require_roles("Restaurant")
def mark_ready(oid: str):
    o = _find_order(oid)
    if g.user_id != o["restaurant_id"]:
        raise ApiError("ERR_FORBIDDEN", "Restaurant identity mismatch.")
    if o["status"] != "PREPARING":
        raise ApiError("ERR_INVALID_STATE", "Order must be in PREPARING.")
    # A rider must have ACCEPTED or PICKED_UP an assignment for this order
    rider_ready = any(
        a["order_id"] == o["id"] and a["status"] in ("ACCEPTED", "PICKED_UP")
        for a in store.assignments.values()
    )
    if not rider_ready:
        raise ApiError("ERR_INVALID_STATE", "No rider has accepted this dispatch yet.")
    with lock():
        o["status"] = "READY_FOR_PICKUP"
        o["updated_at"] = iso_z(now())
        o["version"] += 1
    return success(serialize_order(o))


@bp.post("/<oid>/dispatch")
@require_roles("PlatformAdmin", "CustomerService")
def dispatch_order(oid: str):
    o = _find_order(oid)
    # Re-dispatch creates a fresh OFFERED Assignment as long as the candidate
    # pool is non-empty.
    if o["status"] not in ("RESTAURANT_ACCEPTED", "PREPARING", "READY_FOR_PICKUP"):
        raise ApiError("ERR_INVALID_STATE", "Order is not in a dispatchable state.")
    with lock():
        from dispatch import open_dispatch_offer
        assignment = open_dispatch_offer(o, raise_on_empty=True)
    from serializers import serialize_assignment
    return success(serialize_assignment(assignment), status=201)


@bp.post("/<oid>/returns")
@require_roles("Customer")
def open_return(oid: str):
    o = _find_order(oid)
    if g.user_id != o["customer_id"]:
        raise ApiError("ERR_FORBIDDEN", "Customer identity mismatch.")
    # Duplicate-return check is explicit in PRD §3.9 — surface
    # ERR_DUPLICATE_RETURN even when the order has been moved to
    # REFUND_REQUESTED by the prior return.
    for r in store.returns_.values():
        if r["order_id"] == o["id"] and r["status"] in ("REQUESTED", "APPROVED", "ESCALATED"):
            raise ApiError("ERR_DUPLICATE_RETURN", "An active return already exists for this order.")
    if o["status"] != "DELIVERED":
        raise ApiError("ERR_INVALID_STATE", "Returns are only available on DELIVERED orders.")
    body = get_json_body()
    reason = require_str(body, "reason")
    if reason not in ("QUALITY_ISSUE", "WRONG_ITEM", "LATE", "OTHER"):
        raise ApiError("ERR_VALIDATION", "Invalid return reason.")
    requested_amt = require_int(body, "requested_refund_cents")
    # Temporal window (step 9): 24h from actual_delivery_time
    from datetime import datetime
    from store import iso_z as _iso, now as _now
    actual_dt = _parse_iso(o["actual_delivery_time"])
    if (_now() - actual_dt).total_seconds() > 24 * 3600:
        raise ApiError("ERR_RETURN_WINDOW_EXPIRED", "Return window has expired.")
    # Fiscal amount range (step 10)
    if requested_amt < 1 or requested_amt > o["subtotal_cents"]:
        raise ApiError("ERR_REFUND_AMOUNT_INVALID", "requested_refund_cents out of range.")

    with lock():
        t = now()
        rid = gen_id()
        rec = {
            "id": rid,
            "order_id": o["id"],
            "reason": reason,
            "requested_refund_cents": requested_amt,
            "approved_refund_cents": None,
            "reviewer_cs_user_id": None,
            "status": "REQUESTED",
            "created_at": iso_z(t),
            "updated_at": iso_z(t),
            "version": 1,
        }
        store.returns_[rid] = rec
        # Cascade: order moves to REFUND_REQUESTED
        o["status"] = "REFUND_REQUESTED"
        o["updated_at"] = iso_z(t)
        o["version"] += 1
    return success(serialize_return(rec), status=201)


def _parse_iso(s: str):
    """Parse an ISO 8601 string with Z suffix back to a UTC datetime."""
    from datetime import datetime
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)

"""Clock advance endpoint (PRD §2.10)."""
from __future__ import annotations

from flask import Blueprint

from auth import require_roles
from common import get_json_body, require_number
from envelope import success
from errors import ApiError
from serializers import serialize_assignment
import store
from store import advance_clock, iso_z, lock, now


bp = Blueprint("clock", __name__, url_prefix="/api/_clock")


def _parse_iso(s: str):
    from datetime import datetime
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


@bp.post("/advance")
@require_roles("PlatformAdmin")
def advance():
    body = get_json_body()
    seconds = require_number(body, "seconds")
    if seconds < 0:
        raise ApiError("ERR_VALIDATION", "seconds must be non-negative.")
    with lock():
        advance_clock(seconds)
        # Sweep OFFERED Assignments older than 60s -> REJECTED, then redispatch.
        from routes_assignments import _recompute_acceptance_rate, _recompute_bonus_tier
        from dispatch import open_dispatch_offer

        cur = now()
        swept = []
        for a in list(store.assignments.values()):
            if a["status"] != "OFFERED":
                continue
            age = (cur - _parse_iso(a["offered_at"])).total_seconds()
            if age >= 60:
                a["status"] = "REJECTED"
                rider = store.riders.get(a["rider_id"])
                if rider:
                    hist = store.rider_history.setdefault(
                        rider["id"], {"deliveries": [], "offers": [], "ratings": []}
                    )
                    hist["offers"].append({"accepted": False, "assignment_id": a["id"]})
                    _recompute_acceptance_rate(rider)
                    _recompute_bonus_tier(rider)
                    rider["updated_at"] = iso_z(cur)
                    rider["version"] += 1
                swept.append(a)
        for a in swept:
            order = store.orders.get(a["order_id"])
            if order is None:
                continue
            if order["status"] in ("RESTAURANT_ACCEPTED", "PREPARING", "READY_FOR_PICKUP"):
                # Don't redispatch if some other live assignment already covers it.
                has_live = any(
                    other["order_id"] == order["id"]
                    and other["status"] in ("OFFERED", "ACCEPTED", "PICKED_UP")
                    for other in store.assignments.values()
                )
                if not has_live:
                    open_dispatch_offer(order, raise_on_empty=False)

    return success({"swept": [serialize_assignment(a) for a in swept]})

"""Work order endpoints (PRD §3.10)."""
from __future__ import annotations

from flask import Blueprint, g

from auth import require_roles
from common import get_json_body, optional_str, require_str
from envelope import success
from errors import ApiError
from serializers import serialize_work_order
import store
from store import gen_id, iso_z, lock, now


bp = Blueprint("work_orders", __name__, url_prefix="/api/work-orders")


_VALID_CATEGORIES = {
    "DELIVERY_LATE",
    "FOOD_QUALITY",
    "MISSING_ITEM",
    "RIDER_BEHAVIOR",
    "RESTAURANT_BEHAVIOR",
    "PAYMENT_ISSUE",
    "OTHER",
}


_ROLE_TO_OPEN = {
    "Customer": "CUSTOMER",
    "Rider": "RIDER",
    "Restaurant": "RESTAURANT",
    "CustomerService": "CUSTOMER_SERVICE",
    "PlatformAdmin": "CUSTOMER_SERVICE",  # Admin acts as a CS opener
}


def _find_work_order(wid: str) -> dict:
    w = store.work_orders.get(wid)
    if not w:
        raise ApiError("ERR_NOT_FOUND", "Work order not found.")
    return w


@bp.post("")
@require_roles("Customer", "Rider", "Restaurant", "CustomerService", "PlatformAdmin")
def open_work_order():
    body = get_json_body()
    category = require_str(body, "category")
    if category not in _VALID_CATEGORIES:
        raise ApiError("ERR_VALIDATION", "Invalid category.")
    related_order_id = optional_str(body, "related_order_id")
    related_return_id = optional_str(body, "related_return_id")
    if related_order_id and related_order_id not in store.orders:
        raise ApiError("ERR_NOT_FOUND", "related_order_id not found.")
    if related_return_id and related_return_id not in store.returns_:
        raise ApiError("ERR_NOT_FOUND", "related_return_id not found.")

    # Identity binding for non-CS/Admin roles
    opened_by_role = _ROLE_TO_OPEN[g.role]
    opened_by_id = g.user_id
    if g.role == "Customer" and g.user_id not in store.customers:
        raise ApiError("ERR_FORBIDDEN", "Customer identity mismatch.")
    if g.role == "Rider" and g.user_id not in store.riders:
        raise ApiError("ERR_FORBIDDEN", "Rider identity mismatch.")
    if g.role == "Restaurant" and g.user_id not in store.restaurants:
        raise ApiError("ERR_FORBIDDEN", "Restaurant identity mismatch.")

    with lock():
        t = now()
        wid = gen_id()
        w = {
            "id": wid,
            "opened_by_role": opened_by_role,
            "opened_by_id": opened_by_id,
            "category": category,
            "related_order_id": related_order_id,
            "related_return_id": related_return_id,
            "resolution_notes": None,
            "assigned_cs_user_id": None,
            "status": "OPEN",
            "created_at": iso_z(t),
            "updated_at": iso_z(t),
            "version": 1,
        }
        store.work_orders[wid] = w
    return success(serialize_work_order(w), status=201)


@bp.get("/<wid>")
@require_roles("PlatformAdmin", "CustomerService", "Customer", "Rider", "Restaurant")
def read_work_order(wid: str):
    w = _find_work_order(wid)
    if g.role in ("Customer", "Rider", "Restaurant"):
        if g.user_id != w["opened_by_id"]:
            raise ApiError("ERR_FORBIDDEN", "Identity mismatch.")
    return success(serialize_work_order(w))


